INSERT INTO categories (slug, name, image, description, parent_slug, show_on_homepage, display_order, updated_at) VALUES ('attack-on-titan', 'Attack on Titan', 'https://drive.google.com/thumbnail?id=1qDajomkVQjoTLzUVrowY8pPGo5F_d8Uo&sz=w1000', 'Attack on Titan glass wall posters — Eren, Levi, the Survey Corps and the Titans themselves, crafted on 2.5mm original clear glass with a mirror-like glossy finish that holds the smoke, embers and steel of the series. Pre-installed nano tape included; Small, Medium and Large sizes available.', 'Anime', FALSE, 2, '2026-08-14T14:31:55.482+00:00') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, image = EXCLUDED.image, description = EXCLUDED.description, parent_slug = EXCLUDED.parent_slug, show_on_homepage = EXCLUDED.show_on_homepage, display_order = EXCLUDED.display_order, updated_at = EXCLUDED.updated_at;
INSERT INTO categories (slug, name, image, description, parent_slug, show_on_homepage, display_order, updated_at) VALUES ('car', 'Car Glass Poster', 'https://drive.google.com/thumbnail?id=1hX7-AdIlqxf_56HgxwcpW6JJ4ttr--lY&sz=w1000', 'Supercar and JDM legends on handcrafted glass. The LUMIFLICK Car Glass Poster collection covers Bugatti, Ferrari, Lamborghini, Porsche, BMW M, Mercedes-AMG, Nissan GT-R and Toyota Supra — crafted on 2.5mm original clear glass with a mirror-like glossy finish that makes paint, chrome and tail lights look real. Every piece ships with pre-installed nano tape for a frameless, drill-free mount, and comes in Small (8" x 12"), Medium (12" x 18") and Large (18" x 24"). Ideal automotive wall art for a bedroom, gaming setup, garage, office or showroom, and a strong gift for any car enthusiast in Bangladesh.', NULL, TRUE, 2, '2026-08-15T11:04:07.021+00:00') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, image = EXCLUDED.image, description = EXCLUDED.description, parent_slug = EXCLUDED.parent_slug, show_on_homepage = EXCLUDED.show_on_homepage, display_order = EXCLUDED.display_order, updated_at = EXCLUDED.updated_at;
