INSERT INTO categories (slug, name, image, description, parent_slug, show_on_homepage, display_order, updated_at) VALUES ('nature', 'Nature Glass Poster', 'https://drive.google.com/thumbnail?id=1jdax8vaWlf2O0udugMg8TYNfItBPt4a9&sz=w1000', 'Calm landscapes, tropical water, waterfalls and botanical art on handcrafted glass. Crafted on 2.5mm original clear glass with a mirror-like glossy finish that gives water and foliage real depth. Pre-installed nano tape included; Small, Medium and Large sizes available. Suited to a living room, bedroom, hallway or office where you want the wall to feel quieter.', NULL, TRUE, 6, '2026-08-15T11:02:52.615+00:00') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, image = EXCLUDED.image, description = EXCLUDED.description, parent_slug = EXCLUDED.parent_slug, show_on_homepage = EXCLUDED.show_on_homepage, display_order = EXCLUDED.display_order, updated_at = EXCLUDED.updated_at;
INSERT INTO categories (slug, name, image, description, parent_slug, show_on_homepage, display_order, updated_at) VALUES ('islamic', 'Islamic Glass Poster', 'https://drive.google.com/thumbnail?id=1JiY11H7BxbyKj8NOcCX-AhR2Gu-FZgzO&sz=w1000', 'Islamic calligraphy and holy landmarks on handcrafted glass. The LUMIFLICK Islamic Glass Poster collection brings together Ayatul Kursi, Kalima Tayyiba, Bismillah, Allah and Muhammad calligraphy alongside views of the Kaaba, Masjid al-Haram and Masjid an-Nabawi. Each piece is crafted on 2.5mm original clear glass with a mirror-like glossy finish, so the gold, silver and copper lettering keeps its depth in any light. Pre-installed nano tape is included for a frameless, drill-free mount, and sizes run Small (8" x 12"), Medium (12" x 18") and Large (18" x 24"). A calm, respectful choice for a living room, prayer corner, hallway or office, and a thoughtful gift for Eid, Ramadan, a wedding or a new home.', NULL, TRUE, 7, '2026-08-15T11:02:26.375+00:00') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, image = EXCLUDED.image, description = EXCLUDED.description, parent_slug = EXCLUDED.parent_slug, show_on_homepage = EXCLUDED.show_on_homepage, display_order = EXCLUDED.display_order, updated_at = EXCLUDED.updated_at;
