INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_gohan-hope-glass-poster_1786690964168', 'gohan-hope-glass-poster', 'Gohan Hope Glass Poster', '<p>Gohan Hope from Dragon Ball, crafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish. Glass holds the deep blacks and saturated colour that anime art depends on, so the linework and glow effects stay sharp instead of going flat.</p><p>Available in Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) and Large (18&quot; x 24&quot;). Pre-installed nano tape is included free — mounts in seconds, no nails, no frame, no drilling.</p><p>Scratch-resistant, water and dust proof, colour-guaranteed for life. Anime wall decor for a bedroom, gaming setup, study or office, and a solid gift for any Dragon Ball fan.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1D38oSoJSy4iNp-VOWgQgNi_TU5XWLVUz&sz=w1000', ARRAY[]::text[], 'DragonBall glass poster', 'dragonball', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-14T11:50:51.514073+00:00', '2026-08-17T11:41:11