INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_goku-circle-emblem-glass-poster_1786673741384', 'goku-circle-emblem-glass-poster', 'Goku Circle Emblem Glass Poster', '<p>Bring the energy of Dragon Ball into your room with this Goku Circle Emblem Glass Poster. Crafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish for deep colours and razor-sharp detail.</p><p>Available in Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) and Large (18&quot; x 24&quot;), with a choice of 1, 2 or 3 designs. Pre-installed nano tape is included free, so it mounts in seconds with no nails or drilling.</p><p>Anime wall decor for gamers, otaku bedrooms, living rooms and gifting.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1mZ4AxkpWoGdk3fiWvhvfkJYD4_2CYNZ4&sz=w1000', ARRAY[]::text[], 'DragonBall glass poster', 'dragonball', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-14T11:50:51.514073+00:00', '2026-08-17T11:31:34.787+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, description = EXCLUDED.description, specifications = EXCLUDED.specifications, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, image = EXCLUDED.image, gallery_images = EXCLUDED.gallery_images, category = EXCLUDED.category, category_slug = EXCLUDED.category_slug, tags = EXCLUDED.tags, is_new_drop = EXCLUDED.is_new_drop, is_limited_edition = EXCLUDED.is_limited_edition, is_split_poster = EXCLUDED.is_split_poster, best_seller = EXCLUDED.best_seller, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, sold_count = EXCLUDED.sold_count, inventory = EXCLUDED.inventory, variations = EXCLUDED.variations, updated_at = EXCLUDED.updated_at;
