INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_batman-crimson-cape-glass-poster_1786691073164', 'batman-crimson-cape-glass-poster', 'Batman Crimson Cape Glass Poster', '<p>Batman Crimson Cape. Crafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish, so colour and contrast hold their depth instead of going flat the way matte paper does.</p><p>Available in Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) and Large (18&quot; x 24&quot;). Pre-installed nano tape is included free — it mounts in seconds with no nails, no frame and no drilling.</p><p>Scratch-resistant, water and dust proof, easy to wipe clean and colour-guaranteed for life. Superhero wall decor for a bedroom, living room, gaming setup or office.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1VORATmiu9K0fQ8BLD1ISefsY8TCEU2mT&sz=w1000', ARRAY[]::text[], 'Superhero Glass Poster', 'superhero', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-14T11:50:51.514073+00:00', '2026-08-17T11:41:31.172+00:00') ON CONFLICT (id) DO UPDA