INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_bugatti-chiron-red-glass-poster_1786688920550', 'bugatti-chiron-red-glass-poster', 'Bugatti Chiron Red Glass Poster', '<p>Put a Bugatti Chiron Red on your wall. This LUMIFLICK car poster is crafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish, so bodywork, paint flake and tail lights keep a depth matte paper cannot hold.</p><p>Choose Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) or Large (18&quot; x 24&quot;). Pre-installed nano tape is included free — it mounts in seconds with no nails, no frame and no drilling, and lifts off cleanly if you move it.</p><p>Scratch-resistant, water and dust proof, and colour-guaranteed for life. Automotive wall art for a bedroom, gaming setup, garage, office or showroom — and an easy gift for a Bugatti or JDM fan.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1LJCkF7s0r478jjDWakFFFPUTLCRaPdJg&sz=w1000', ARRAY[]::text[], 'Car Glass Poster', 'car', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-1