INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_porsche-red-detail-glass-poster_1786909245569', 'porsche-red-detail-glass-poster', 'Porsche Red Detail Glass Poster', '<p>Porsche is celebrated for precision, performance, and design that feels instantly recognisable. This Porsche-inspired glass artwork captures that spirit through bold red accents, deep blacks, and close-up automotive details that reward a second look. Choose the individual design or designs that fit your space.</p><p>More than wall décor, it gives a car enthusiast’s bedroom, gaming setup, living room, office, or garage-inspired space a sharper, more personal identity. Crafted on 2.5mm original clear glass, the mirror-like glossy reflective finish adds depth and lets the artwork come alive as the light changes.</p><p>Available in Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;), and Large (18&quot; x 24&quot;). Every poster includes free pre-installed nano tape for mounting in seconds—no nails, frame, or drilling needed. Scratch-, water-, and dust-resistant, with colour guaranteed for life, it makes an excellent gift for anyone who appreciates Porsche design.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1Bzhzxy51w1_x5y4H4Fo5mdVEJBVuginR&sz=s0', ARRAY[]::text[], 'Car Glass Poster', 'car', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-16T19:40:46.500356+00:00', '2026-08-17T11:36:03.866+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, description = EXCLUDED.description, specifications = EXCLUDED.specifications, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, image = EXCLUDED.image, gallery_images = EXCLUDED.gallery_images, category = EXCLUDED.category, category_slug = EXCLUDED.category_slug, tags = EXCLUDED.tags, is_new_drop = EXCLUDED.is_new_drop, is_limited_edition = EXCLUDED.is_limited_edition, is_split_poster = EXCLUDED.is_split_poster, best_seller = EXCLUDED.best_seller, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, sold_count = EXCLUDED.sold_count, inventory = EXCLUDED.inventory, variations = EXCLUDED.variations, updated_at = EXCLUDED.updated_at;
INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_hogwarts-house-crest-glass-poster_1786962915090', 'hogwarts-house-crest-glass-poster', 'Hogwarts House Crest Glass Poster', '<p>Gryffindor, Slytherin or Hufflepuff — pick the crest that matches your house. This LUMIFLICK poster is handcrafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish, so the gold thread and house colours hold real depth under lamplight instead of sitting flat like matte paper.</p><p>Choose Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) or Large (18&quot; x 24&quot;). Pre-installed nano tape is included free — it mounts in seconds with no nails, no frame and no drilling, and lifts off cleanly if you move it.</p><p>Scratch-resistant, water and dust proof, and colour-guaranteed for life. A house-pride centerpiece for a bedroom, dorm, gaming setup or office — and an easy gift for any Harry Potter fan.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1u5ho756nfW0uDuobjNdRahmL4tA9JWsI&sz=w1000', ARRAY[]::text[], 'Harry Potter', 'harry-potter', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-17T10:35:16.053838+00:00', '2026-08-17T11:36:02.742+00:00') ON CONFLICT (id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, description = EXCLUDED.description, specifications = EXCLUDED.specifications, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, image = EXCLUDED.image, gallery_images = EXCLUDED.gallery_images, category = EXCLUDED.category, category_slug = EXCLUDED.category_slug, tags = EXCLUDED.tags, is_new_drop = EXCLUDED.is_new_drop, is_limited_edition = EXCLUDED.is_limited_edition, is_split_poster = EXCLUDED.is_split_poster, best_seller = EXCLUDED.best_seller, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, sold_count = EXCLUDED.sold_count, inventory = EXCLUDED.inventory, variations = EXCLUDED.variations, updated_at = EXCLUDED.updated_at;
