ug = EXCLUDED.slug, title = EXCLUDED.title, description = EXCLUDED.description, specifications = EXCLUDED.specifications, price = EXCLUDED.price, compare_at_price = EXCLUDED.compare_at_price, image = EXCLUDED.image, gallery_images = EXCLUDED.gallery_images, category = EXCLUDED.category, category_slug = EXCLUDED.category_slug, tags = EXCLUDED.tags, is_new_drop = EXCLUDED.is_new_drop, is_limited_edition = EXCLUDED.is_limited_edition, is_split_poster = EXCLUDED.is_split_poster, best_seller = EXCLUDED.best_seller, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, sold_count = EXCLUDED.sold_count, inventory = EXCLUDED.inventory, variations = EXCLUDED.variations, updated_at = EXCLUDED.updated_at;
INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_harry-potter-wand-and-castle-glass-poster_1786963587886', 'harry-potter-wand-and-castle-glass-poster', 'Harry Potter Wand and Castle Glass Poster', '<p>A lit wand, a sunset over Hogwarts, and the Harry Potter emblem wrapped in mist — three ways to bring the wizarding world onto your wall. Handcrafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish that gives the artwork real depth.</p><p>Available in Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) and Large (18&quot; x 24&quot;). Free pre-installed nano tape mounts in seconds, no nails or drilling required.</p><p>Scratch, water and dust resistant, colour guaranteed for life. A great fit for a bedroom, reading corner or gaming setup, and a solid gift for any fan.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1efYWp-oPCpDYnMAjENYw6xYnc-4gGK_Z&sz=w1000', ARRAY[]::text[], 'Harry Potter', 'harry-potter', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-17T10:46:28.419519+00:00', '2026-08-