INSERT INTO products (id, slug, title, description, specifications, price, compare_at_price, image, gallery_images, category, category_slug, tags, is_new_drop, is_limited_edition, is_split_poster, best_seller, rating, review_count, sold_count, inventory, variations, created_at, updated_at) VALUES ('prod_platform-9-3-4-glass-poster_1786963588919', 'platform-9-3-4-glass-poster', 'Platform 9 3-4 Glass Poster', '<p>The handwritten supply list, the brick archway sign, and the steam of the Hogwarts Express — a nostalgic trio for anyone who has waited at platform nine and three-quarters. Handcrafted on 2.5mm original clear glass with a mirror-like glossy, reflective finish.</p><p>Choose Small (8&quot; x 12&quot;), Medium (12&quot; x 18&quot;) or Large (18&quot; x 24&quot;). Free pre-installed nano tape mounts in seconds — no nails, no frame, no drilling.</p><p>Scratch, water and dust resistant, colour guaranteed for life. Perfect for a bedroom, hallway or office, and a thoughtful gift for a Harry Potter fan.</p>', '{"finish":"Mirror like Glossy and Reflective Finishing","weight":".8-6kg","material":"2.5mm Original Clear Glass","mounting":"Pre-installed Nano tape FREE with each poster","dimensions":"Small (8\" x 12\") | Medium (12\" x 18\") | Large (18\" x 24\")","frameColorOptions":["Matte Black","Luxury Gold","Natural Walnut Wood","Minimalist White"]}', 550, NULL, 'https://drive.google.com/thumbnail?id=1fSLRdfYI_n_MesKnhaFZIch0XFv3JMX4&sz=w1000', ARRAY[]::text[], 'Harry Potter', 'harry-potter', ARRAY[]::text[], FALSE, FALSE, FALSE, FALSE, 5, 0, 0, 100, '[{"size":"Small (8\" x 12\")","label":"Small (8\" x 12\")","price":550,"inStock":true,"regularPrice":650},{"size":"Medium (12\" x 18\")","label":"Medium (12\" x 18\")","price":850,"inStock":true,"regularPrice":1000},{"size":"Large (18\" x 24\")","label":"Large (18\" x 24\")","price":1550,"inStock":true,"regularPrice":1780}]'::jsonb, '2026-08-17T10:46:29.468073+00:00', '2026-08-17T11:36:00.675+00:00') ON CONFLICT (id) DO UP